#include <iostream>
#include <vector>
#include <string>
#include <map>
using namespace std;

vector<int> parent, sizes;

int findRoot(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

bool unite(int a, int b) {
    a = findRoot(a);
    b = findRoot(b);
    if (a == b) return false;
    if (sizes[a] < sizes[b]) swap(a, b);
    parent[b] = a;
    sizes[a] += sizes[b];
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<vector<long long>> stones(n, vector<long long>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> stones[i][j];
        }
    }

    map<pair<int, long long>, int> ids;
    vector<pair<int, int>> pairsList;
    for (const vector<long long>& s : stones) {
        int a, b;
        auto itRow = ids.find({0, s[0]});
        if (itRow == ids.end()) {
            a = (int)ids.size();
            ids[{0, s[0]}] = a;
        } else {
            a = itRow->second;
        }
        auto itCol = ids.find({1, s[1]});
        if (itCol == ids.end()) {
            b = (int)ids.size();
            ids[{1, s[1]}] = b;
        } else {
            b = itCol->second;
        }
        pairsList.push_back({a, b});
    }
    int count = (int)ids.size();
    parent.resize(count);
    sizes.assign(count, 1);
    for (int v = 0; v < count; v++) parent[v] = v;
    long long groups = count;
    for (const auto& pr : pairsList) {
        if (unite(pr.first, pr.second)) groups--;
    }
    cout << n - groups << "\n";

    return 0;
}

