import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[] parent;
    static int[] sizes;

    static int findRoot(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    static boolean unite(int a, int b) {
        a = findRoot(a);
        b = findRoot(b);
        if (a == b) return false;
        if (sizes[a] < sizes[b]) {
            int t = a;
            a = b;
            b = t;
        }
        parent[b] = a;
        sizes[a] += sizes[b];
        return true;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[][] stones = new long[(int) n][2];
        for (int i = 0; i < stones.length; i++) {
            for (int j = 0; j < stones[i].length; j++) {
                stones[i][j] = Long.parseLong(next());
            }
        }

        Map<String, Integer> ids = new HashMap<>();
        List<int[]> pairsList = new ArrayList<>();
        for (long[] s : stones) {
            int a = ids.computeIfAbsent("r" + s[0], k -> ids.size());
            int b = ids.computeIfAbsent("c" + s[1], k -> ids.size());
            pairsList.add(new int[] {a, b});
        }
        int count = ids.size();
        parent = new int[count];
        sizes = new int[count];
        for (int v = 0; v < count; v++) {
            parent[v] = v;
            sizes[v] = 1;
        }
        long groups = count;
        for (int[] pr : pairsList) {
            if (unite(pr[0], pr[1])) groups--;
        }
        System.out.println(n - groups);
    }
}
